class Popu
{
  pos, vel, acc;
  Id;
  Type;
  Infect;
  Time;
  Immunise;
  Live;  
  constructor(x, y,nid,type,infect,time,immunise, live)
  {
    pos = new PVector(x, y);
    vel = new PVector(0, 0);
    acc = new PVector(0, 0);
    Id=nid;
    Type=type;
    Infect=infect;
    Time=time;
    Immunise=immunise;
    Live=live;   
    if(Type==0)
      {
        vel.x=random(-vitY,vitY);
        vel.y=random(-vitY,vitY);
      }
    if(Type==1)
      {
        vel.x=random(-vitS,vitS);
        vel.y=random(-vitS,vitS);
      }
     if(Type==2)
      {
        vel.x=random(-vitO,vitO);
        vel.y=random(-vitO,vitO);
      }
  }

  function timeVirus()
  {
    if(Infect>0)
      {
        Time++;
        if (Time==TimeI)
          {
            Infect=2;           
          }
        if(Time==TimeD)
          {
            Infect=3;
          }
        if(Time==TimeE)
          {
            surviveR=random(1);
            if (Type==0 & surviveR > surviveRY)      // Young
              {
                Live=false;                          // let surviveRY=0.8 ==>20% mortality
              }
           if (Type==1 & surviveR > surviveRS)      // Senior
              {
                Live=false;                         // let surviveRY=0.6 ==>40% mortality
              }
            if (Type==2 & surviveR > surviveRO)      // Old
              {
                Live=false;                         // let surviveRY=0.4 ==>60% mortality
              }            
            else
              {
                Infect=0;                           // let Immunise=true;
                Time=0;
              }
          }
      }
  }

  function submitVirus(p)
  {
    let d=pos.dist(p.pos);
    if(d<10)
      {
        if(p.Infect>0)
          {            
            if(Type==0 & Immunise==false)
              contamin=random(contamineRY);
            else if(Type==1 & Immunise==false)
              contamin=random(contamineRS);
            else if(Type==2 & Immunise==false)
              contamin=random(contamineRO);
            //println(contamin);
            if (Infect==0 & (contamin> 0.2) & Immunise==false)
              {
                Infect=1;
                Rinfect++;
              }          
          }
      }
  } 

  function display()
  {
    stroke(black);
    strokeWeight(1);
    if(Infect==0 & Immunise==false)
      fill(green);
    else if(Infect==0 & Immunise==true)
      fill(blue);
    else if(Infect==1)
      fill(yellow);
    else if(Infect==2)
      fill(red);
    else if (Infect==3)
      fill(black);    
    if(Type==0)
      rect(pos.x, pos.y, 15,15);
    else if (Type==1)
      ellipse(pos.x, pos.y, 16,16);
    else if (Type==2)
      //ellipse(pos.x,pos.y,16,9);
      triangle(pos.x-10,pos.y-10,pos.x+10,pos.y-10,pos.x,pos.y+10);    
    //textAlign(CENTER); 
    //textSize(6); 
    //fill(0);
    //text(Id, pos.x, pos.y);   
  }

  function update()
  { 
    if(Infect<2)
      {
        pos.add(vel);
      }
    if(pos.x < 60)
      {
        vel.x *= -1;
        pos.x =pos.x+ vel.x+0;            
      }
    if(pos.x >= width-60)
      {
        vel.x *= -1;
        pos.x = pos.x+vel.x-0;
      }
    if(pos.y <70)
      {
        vel.y *= -1;
        pos.y = pos.y+vel.y+0;
      }
    if(pos.y >= height-70)
      {
        vel.y *= -1;
        pos.y =pos.y+ vel.y-0;
      }
  }
}

